/* eslint-disable no-undef */
import { Component, Element, Event, EventEmitter, Host, Prop, Watch, h } from '@stencil/core';
import { IndicatorDesign } from '../../types';

/**
 * @nativeEvent groupuiSortClick - dispatched when the sort icon is clicked => 'event.details' delivers the property order and the index (HINT: on event dispatched sortable logic has to be implemented by yourself)
 */

@Component({
  tag: 'groupui-table',
  styleUrl: 'table.scss',
  shadow: true,
})
export class Table {
  @Element() host: HTMLElement;

  /**
   * table rows in alternate colors
   */
  @Prop({ reflect: true }) readonly striped: boolean;

  /**
   * sets the cell size
   */
  @Prop({ reflect: true }) readonly size: 's' | 'm' | 'l' = 'm';

  /**
   * defines a table as sortable if header row is present (HINT: just an indicator - sortable logic has to be implemented by yourself)
   */
  @Prop({ reflect: true }) readonly sortable: boolean;

  /**
   * sets the icon for the indicator
   */
  @Prop({ reflect: true }) readonly indicator: IndicatorDesign = 'default';

  /**
   * defines the columns of the table
   */
  @Prop({ reflect: true }) readonly columns: number = 1;

  /**
   * defines the width of the columns (e.g. for a table with 4 columns: auto 100px auto auto)
   */
  @Prop({ reflect: true }) readonly widths: string;

  /**
   * defines all cells of the first row as header
   */
  @Prop({ reflect: true }) readonly header: boolean;

  /**
   * defines all cells of the first row as sticky
   */
  @Prop({ reflect: true }) readonly sticky: boolean;

  /**
   * enables horizontal scrollbars
   */
  @Prop({ reflect: true }) readonly scrollX: boolean;

  /**
   * enables vertical scrollbars
   */
  @Prop({ reflect: true }) readonly scrollY: boolean;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  private inheritAttributesFromHeader() {
    const headerCells = this.host.querySelectorAll(
      'groupui-table-cell[header]'
    ) as NodeListOf<HTMLGroupuiTableCellElement>;

    if (headerCells && headerCells.length > 0) {
      this.inheritSortingFromHeader(headerCells);
    }
  }

  private inheritSortingFromHeader(headerCells) {
    if (this.sortable) {
      headerCells.forEach((cell) => cell.setAttribute('sortable', ''));
      headerCells.forEach((cell) => cell.setAttribute('indicator', this.indicator));
    }
  }

  private getRowsOfGrid(): number {
    return this.getCellsOfGrid() / this.getColumns();
  }

  private getCellsOfGrid(): number {
    let cellCounter = 0;
    const cells = this.host.querySelectorAll('groupui-table-cell') as NodeListOf<HTMLGroupuiTableCellElement>;
    cells.forEach((cell) => {
      cellCounter = cellCounter + this.getColspanOfCell(cell);
    });
    return cellCounter;
  }

  private getCellsOfRow(rowIndex: number): NodeListOf<HTMLGroupuiTableCellElement> {
    return this.host.querySelectorAll(
      `groupui-table-cell[row="${rowIndex}"]`
    ) as NodeListOf<HTMLGroupuiTableCellElement>;
  }

  private setRowAttributes() {
    let currentRow = 0;
    let columnsCounter = this.getColumns();
    const tableCells = this.host.querySelectorAll('groupui-table-cell');
    tableCells.forEach((cell: HTMLGroupuiTableCellElement) => {
      if (columnsCounter === 0) {
        currentRow++;
        columnsCounter = this.getColumns();
      }
      columnsCounter = columnsCounter - this.getColspanOfCell(cell);
      cell.setAttribute('row', currentRow.toString());
    });
  }

  private getColspanOfCell(cell: HTMLGroupuiTableCellElement): number {
    const colspanOfCell = parseInt(cell.getAttribute('colspan'));
    return isNaN(colspanOfCell) ? 1 : colspanOfCell;
  }

  private isUnevenRow(cell: HTMLGroupuiTableCellElement): boolean {
    return parseInt(cell.getAttribute('row')) % 2 === 1;
  }

  private getGridTemplateColumnsCSS(): string {
    if (this.widths) {
      return this.widths;
    }
    return this.autoColumnWidths();
  }

  private autoColumnWidths(): string {
    const widths = [];
    for (let i = 0; i < this.getColumns(); i++) {
      widths.push('auto');
    }
    return widths.join(' ');
  }

  private handleColspanOfChildCells() {
    for (let i = 0; i < this.getRowsOfGrid(); i++) {
      let columnCounter = 1;
      this.getCellsOfRow(i).forEach((cell) => {
        const colspanOfCell = this.getColspanOfCell(cell);
        if (colspanOfCell > 1) {
          cell.style.gridColumn = `${columnCounter} / ${columnCounter + colspanOfCell}`;
        }
        columnCounter = columnCounter + colspanOfCell;
      });
    }
  }

  private updateHeaderAttributeOfChildCells() {
    if (this.header) {
      this.getCellsOfRow(0).forEach((cell) => {
        cell.setAttribute('header', '');
      });
    }
  }

  private updateStickyAttributeOfChildCells() {
    if (this.sticky) {
      this.getCellsOfRow(0).forEach((cell) => {
        cell.setAttribute('sticky', '');
      });
    }
  }

  private getColumns() {
    return this.columns < 1 ? 1 : this.columns;
  }

  componentDidRender() {
    this.setRowAttributes();
    this.updateSizePropOfChildCells();
    this.updateStripedPropOfChildCells();
    this.updateHeaderAttributeOfChildCells();
    this.updateStickyAttributeOfChildCells();
    this.handleColspanOfChildCells();
    this.inheritAttributesFromHeader();
  }

  private rerenderOnSlotChange = () => {
    this.componentDidRender();
  };

  @Watch('size')
  updateSizePropOfChildCells() {
    const tableCells = this.host.querySelectorAll('groupui-table-cell');
    tableCells.forEach((cell: HTMLGroupuiTableCellElement) => {
      cell.setAttribute('size', this.size);
    });
  }

  @Watch('striped')
  updateStripedPropOfChildCells() {
    const tableCells = this.host.querySelectorAll('groupui-table-cell');
    tableCells.forEach((cell: HTMLGroupuiTableCellElement) => {
      if (this.striped) {
        cell.classList.add('no-hover');
        if (this.isUnevenRow(cell)) {
          cell.setAttribute('striped', '');
        } else {
          cell.removeAttribute('striped');
        }
      } else {
        cell.classList.remove('no-hover');
        cell.removeAttribute('striped');
      }
    });
  }

  render() {
    return (
      <Host>
        <div class="container" style={{ gridTemplateColumns: this.getGridTemplateColumnsCSS() }}>
          <slot onSlotchange={this.rerenderOnSlotChange} />
        </div>
      </Host>
    );
  }
}
